      });
    } else if (D.roomId && D.lockToken) {
      locksToRelease.push({ roomId: D.roomId, lockToken: D.lockToken });
    }

    const cleanDraft = {
      checkIn: D.checkIn,
      checkOut: D.checkOut,
      adults: 1,
      children: 0,
      hasPet: true
    };

    return [output(
      petRejectMessage,
      keep(cleanDraft, 'seleccion_habitacion'),
      {
        api_action: 'pet_reject_relist',
        pet_reject_message: petRejectMessage,
        locks_to_release: locksToRelease,
        checkIn: D.checkIn,
