    parsed = JSON.parse(rawText.replace(/^```(?:json)?\s*|\s*```$/g, '').trim());
} catch (e) {
    parsed = {};
}

const toValidIso = (y, m, d) => {
    const iso = String(y) + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
    const dt = new Date(iso + 'T00:00:00Z');
    return !isNaN(dt.getTime()) && dt.toISOString().slice(0, 10) === iso ? iso : null;
};

const isValidIso = (s) => {
    if (typeof s !== 'string') return false;
    const m = s.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return m ? Boolean(toValidIso(m[1], m[2], m[3])) : false;
};

const extractExplicitDates = (s) => {
    const found = [];
    const rx = /(\d{4})[-/](\d{1,2})[-/](\d{1,2})|(\d{1,2})[-/](\d{1,2})[-/](\d{4})/g;
    let m;
    while ((m = rx.exec(s)) !== null) {
        const iso = m[1] ? toValidIso(m[1], m[2], m[3]) : toValidIso(m[6], m[5], m[4]);
        if (iso) found.push(iso);
    }
    return found;
};

const explicitDates = extractExplicitDates(rawUserText);

// Merge acumulativo: nuevo dato válido > respaldo determinista > dato previo guardado
let checkIn = isValidIso(parsed.checkIn) ? parsed.checkIn.trim() : (explicitDates[0] || (isValidIso(prev.checkIn) ? prev.checkIn : null));
let checkOut = isValidIso(parsed.checkOut) ? parsed.checkOut.trim() : (explicitDates[1] || (isValidIso(prev.checkOut) ? prev.checkOut : null));

const parsedAdults = (parsed.adults !== null && parsed.adults !== undefined && !isNaN(Number(parsed.adults)) && Number(parsed.adults) >= 1)
